<?php
require __DIR__.'/includes/bootstrap.php';$admin=music_require_admin($mysqli);
$settings=[];$result=$mysqli->query("SELECT setting_key,setting_value FROM music_ai_settings WHERE setting_key LIKE 'daily_agent_%'");while($row=$result->fetch_assoc())$settings[$row['setting_key']]=$row['setting_value'];
$worker=$mysqli->query("SELECT * FROM music_ai_workers ORDER BY heartbeat_at DESC LIMIT 1")->fetch_assoc();$health=json_decode((string)($worker['health_json']??''),true)?:[];
$queue=$mysqli->query("SELECT status,COUNT(*) total FROM music_ai_jobs GROUP BY status");$queueCounts=[];while($row=$queue->fetch_assoc())$queueCounts[$row['status']]=(int)$row['total'];
$active=$mysqli->query("SELECT r.*,t.title,t.genre,t.current_stage track_stage,t.progress_percent track_progress,j.attempts job_attempts,j.next_attempt_at FROM music_ai_agent_runs r LEFT JOIN music_ai_tracks t ON t.id=r.track_id LEFT JOIN music_ai_jobs j ON j.agent_run_id=r.id AND j.status IN ('PENDING','PROCESSING') WHERE r.status IN ('QUEUED','RUNNING','RECOVERING') ORDER BY r.id DESC LIMIT 1")->fetch_assoc();
$runs=[];$rows=$mysqli->query("SELECT r.*,t.title,t.genre,t.is_published,j.attempts job_attempts,j.next_attempt_at FROM music_ai_agent_runs r LEFT JOIN music_ai_tracks t ON t.id=r.track_id LEFT JOIN music_ai_jobs j ON j.agent_run_id=r.id ORDER BY r.id DESC LIMIT 50");while($row=$rows->fetch_assoc())$runs[]=$row;
$heartbeatAge=$worker?time()-strtotime($worker['heartbeat_at']):null;$workerOnline=$worker&&$worker['status']!=='STOPPED'&&$heartbeatAge<max(120,(int)music_setting($mysqli,'worker_timeout_minutes','20')*60);
?>
